class Solution {
public:
    int maxProduct(vector<string>& words) {
        unordered_map<int, int> masks;
        for (const string& w : words) {
            int mask = 0;
            for (char ch : w) {
                mask |= 1 << (ch - 'a');
            }
            masks[mask] = max(masks[mask], (int)w.size());
        }
        int maxProd = 0;
        vector<pair<int, int>> items(masks.begin(), masks.end());
        int m = items.size();
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                if ((items[i].first & items[j].first) == 0) {
                    maxProd = max(maxProd, items[i].second * items[j].second);
                }
            }
        }
        return maxProd;
    }
};

class Solution {
    public int maxProduct(String[] words) {
        Map<Integer, Integer> masks = new HashMap<>();
        for (String w : words) {
            int mask = 0;
            for (int i = 0; i < w.length(); i++) {
                mask |= 1 << (w.charAt(i) - 'a');
            }
            masks.put(mask, Math.max(masks.getOrDefault(mask, 0), w.length()));
        }
        int maxProd = 0;
        List<Map.Entry<Integer, Integer>> items = new ArrayList<>(masks.entrySet());
        int m = items.size();
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                if ((items.get(i).getKey() & items.get(j).getKey()) == 0) {
                    maxProd = Math.max(maxProd, items.get(i).getValue() * items.get(j).getValue());
                }
            }
        }
        return maxProd;
    }
}

var maxProduct = function(words) {
    const masks = new Map();
    for (const w of words) {
        let mask = 0;
        for (let i = 0; i < w.length; i++) {
            mask |= 1 << (w.charCodeAt(i) - 97);
        }
        masks.set(mask, Math.max(masks.get(mask) || 0, w.length));
    }
    let maxProd = 0;
    const items = Array.from(masks.entries());
    const m = items.length;
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            if ((items[i][0] & items[j][0]) === 0) {
                maxProd = Math.max(maxProd, items[i][1] * items[j][1]);
            }
        }
    }
    return maxProd;
};
